function countStatus(s){return orders.value.filter(o=>o.status===s).length}
function localDateKey(value){const date=new Date(value);return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function itemCount(o){return o.items.reduce((s,i)=>s+i.qty,0)}
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n)}
function formatDate(d){return new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(d))}
function formatShortDate(d){return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(d))}
function ledgerLabel(type){return({opening:'期初库存',reserve:'预占库存',release:'释放预占',ship:'发货扣减',adjust:'手动调整'})[type]||type}
function statusLabel(s){return({processing:'待处理',ready:'待发货',shipped:'已发货',completed:'已完成',cancelled:'已取消'})[s]}
function statusClass(s){return`status-${s}`}
function progressIndex(s){return({processing:0,ready:1,shipped:2,completed:3,cancelled:-1})[s]}
function flagFor(c){return({美国:'🇺🇸',加拿大:'🇨🇦',英国:'🇬🇧',澳大利亚:'🇦🇺',德国:'🇩🇪',日本:'🇯🇵',法国:'🇫🇷'})[c]||'🌍'}
function productBySku(s){return products.value.find(p=>p.sku===s)}
function orderEventLabel(type){return({confirm:'确认订单',cancel:'取消订单',ship:'登记发货',complete:'完成订单',inventory_review:'库存待复核'})[type]||type}
function roleLabel(role){return({admin:'管理员',operator:'运营',viewer:'只读'})[role]||role}
function userAuditLabel(event){if(event.type==='created')return`创建账号（${roleLabel(event.newRole)}）`;if(event.type==='role_changed')return`角色：${roleLabel(event.oldRole)} → ${roleLabel(event.newRole)}`;return event.type==='disabled'?'停用账号':'重新启用账号'}
function orderTimeline(o){const index=progressIndex(o.status);return progressSteps.map((label,i)=>({label,time:i===0?formatDate(o.date):((o.events||[]).find(event=>event.toStatus===(['processing','ready','shipped','completed'][i]))?formatDate((o.events||[]).find(event=>event.toStatus===(['processing','ready','shipped','completed'][i])).date):index>=i?'状态记录待补充':'等待上一步完成'),active:i<=index,future:i>index}))}
function showToast(m,k='success'){toastMessage.value=m;toastKind.value=k;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastMessage.value='',3000)}
function workspaceKey(value){return value==='order-detail'?'orders':value}
function navigate(target,filter=null,recordHistory=true){const current=workspaceKey(page.value);if(recordHistory&&target!==current)workspaceHistory.value.push(current);page.value=target;mobileMenuOpen.value=false;if(target==='orders'){selectedOrderId.value=null;orderStatusFilter.value=filter||'all';orderSearch.value=''}if(target==='backups'&&currentUser.value?.role==='admin')loadBackups();if(target==='shipments'&&!shipmentOrders.value.some(o=>o.id===selectedShipmentId.value))selectShipment(shipmentOrders.value[0]?.id||null);if(location.hash!==`#/${target}`&&target!=='order-detail')history.replaceState(null,'',`#/${target}`)}
function goBackWorkspace(){const target=workspaceHistory.value.pop()||'dashboard';navigate(target,null,false)}
function openOrder(id){const current=workspaceKey(page.value);if(current!=='orders')workspaceHistory.value.push(current);else workspaceHistory.value.push('orders');selectedOrderId.value=id;page.value='order-detail';mobileMenuOpen.value=false;history.replaceState(null,'',`#/orders/${id}`)}
function demoIconName(icon){return icon===BriefcaseBusiness?'BriefcaseBusiness':icon===Activity?'Activity':icon===Globe2?'Globe2':icon===Lightbulb?'Lightbulb':icon===PackageCheck?'PackageCheck':'Package'}
function demoReserved(sku){return orders.value.filter(order=>order.status==='ready').reduce((sum,order)=>sum+order.items.filter(item=>item.sku===sku).reduce((n,item)=>n+item.qty,0),0)}
function demoProductRows(){return products.value.map(product=>({...product,icon:demoIconName(product.icon),reserved:demoReserved(product.sku),available:product.stock-demoReserved(product.sku)}))}
function saveDemoData(){if(!DEMO_MODE)return;const payload={products:products.value.map(product=>({...product,icon:demoIconName(product.icon)})),orders:orders.value,inventoryLedger:inventoryLedger.value};try{localStorage.setItem(DEMO_STORAGE_KEY,JSON.stringify(payload))}catch{throw new Error('浏览器存储空间不足，演示数据未能保存。请先下载备份或清理部分数据。')}}
function loadDemoData(){try{const saved=JSON.parse(localStorage.getItem(DEMO_STORAGE_KEY)||'null');if(!saved||!Array.isArray(saved.products)||!Array.isArray(saved.orders)){saveDemoData();return}const icons={BriefcaseBusiness,Activity,Globe2,Lightbulb,PackageCheck,Package};products.value=saved.products.map(product=>({...product,icon:icons[product.icon]||Package}));orders.value=saved.orders;inventoryLedger.value=Array.isArray(saved.inventoryLedger)?saved.inventoryLedger:[]}catch{localStorage.removeItem(DEMO_STORAGE_KEY);saveDemoData()}}
function addDemoLedger({sku,type,quantityDelta=0,reservedDelta=0,orderId='',note=''}){const product=products.value.find(item=>item.sku===sku);if(!product)return;const reserved=demoReserved(sku);inventoryLedger.value.unshift({id:`demo-${Date.now()}-${Math.random()}`,date:new Date().toISOString(),sku,orderId,type,quantityDelta,reservedDelta,stockAfter:product.stock,reservedAfter:reserved,note,changedBy:'本地演示'})}
function readDemoBackups(){try{return JSON.parse(localStorage.getItem(DEMO_BACKUP_KEY)||'[]')}catch{return []}}
function demoApi(path,options={}){const method=options.method||'GET',body=options.body?JSON.parse(options.body):{},route=decodeURI(path.split('?')[0]);if(route==='/auth/logout')return{};if(route==='/products'&&method==='GET')return demoProductRows();if(route==='/orders'&&method==='GET')return orders.value.map(order=>({...order,items:order.items.map(item=>({...item,name:item.name||products.value.find(product=>product.sku===item.sku)?.name||item.sku}))}));if(route==='/inventory/ledger'&&method==='GET')return inventoryLedger.value;if(route==='/orders/demo'&&method==='POST'){const product=products.value.find(item=>item.sku===body.sku);if(!product)throw new Error('请选择有效商品');const quantity=Number(body.quantity);if(!Number.isInteger(quantity)||quantity<1)throw new Error('商品数量需为正整数');const subtotal=product.price*quantity,shipping=Number(body.shipping)||0;return{id:`TF-DEMO-${Date.now()}`,date:new Date().toISOString(),country:String(body.country||'美国'),status:'processing',items:[{sku:product.sku,name:product.name,qty:quantity,price:product.price}],subtotal,shipping,total:subtotal+shipping,events:[]}}
if(route.startsWith('/orders/')){const parts=route.split('/').filter(Boolean),id=decodeURIComponent(parts[1]||''),action=parts[2],order=orders.value.find(item=>item.id===id);if(!order)throw new Error('未找到该订单');if(action==='confirm'&&method==='POST'){if(order.status!=='processing')throw new Error('只有待处理订单可以确认');for(const item of order.items){const product=products.value.find(row=>row.sku===item.sku);if(!product||product.stock-demoReserved(item.sku)<item.qty)throw new Error(`商品 ${item.sku} 可用库存不足，无法确认订单`)}order.status='ready';order.events=order.events||[];order.events.push({id:`event-${Date.now()}`,type:'confirm',date:new Date().toISOString(),toStatus:'ready',changedBy:'本地演示'});order.items.forEach(item=>addDemoLedger({sku:item.sku,type:'reserve',reservedDelta:item.qty,orderId:id,note:'确认订单，预占库存'}));saveDemoData();return order}if(action==='cancel'&&method==='POST'){if(!['processing','ready'].includes(order.status))throw new Error('当前状态不能取消订单');const wasReady=order.status==='ready';order.status='cancelled';if(wasReady)order.items.forEach(item=>addDemoLedger({sku:item.sku,type:'release',reservedDelta:-item.qty,orderId:id,note:'Release reserved inventory'}));order.cancelReason=String(body.reason||'演示取消');order.events=order.events||[];order.events.push({id:`event-${Date.now()}`,type:'cancel',date:new Date().toISOString(),toStatus:'cancelled',changedBy:'本地演示',reason:order.cancelReason});saveDemoData();return order}if(action==='ship'&&method==='POST'){if(order.status!=='ready')throw new Error('只有待发货订单可以发货');order.items.forEach(item=>{const product=products.value.find(row=>row.sku===item.sku);if(!product||product.stock<item.qty)throw new Error(`商品 ${item.sku} 库存不足`)});order.status='shipped';order.items.forEach(item=>{const product=products.value.find(row=>row.sku===item.sku);product.stock-=item.qty;addDemoLedger({sku:item.sku,type:'ship',quantityDelta:-item.qty,reservedDelta:-item.qty,orderId:id,note:'Ship demo order'})});order.carrier=String(body.carrier||'');order.tracking=String(body.tracking||'');order.events=order.events||[];order.events.push({id:`event-${Date.now()}`,type:'ship',date:new Date().toISOString(),toStatus:'shipped',changedBy:'本地演示'});saveDemoData();return order}if(action==='complete'&&method==='POST'){if(order.status!=='shipped')throw new Error('只有已发货订单可以完成');order.status='completed';order.events=order.events||[];order.events.push({id:`event-${Date.now()}`,type:'complete',date:new Date().toISOString(),toStatus:'completed',changedBy:'本地演示'});saveDemoData();return order}}
if(route==='/products'&&method==='POST'){const sku=String(body.sku||'').trim();if(products.value.some(item=>item.sku===sku))throw new Error('SKU 已存在');const product={sku,name:String(body.name||''),category:String(body.category||'其他'),price:Number(body.price),stock:Number(body.stock),threshold:LOW_STOCK_THRESHOLD,active:true,theme:'thumb-blue',icon:Package,description:String(body.description||''),reserved:0,available:Number(body.stock)};if(!product.name||!sku||!Number.isFinite(product.price)||product.price<=0||!Number.isInteger(product.stock)||product.stock<0)throw new Error('商品信息无效');return{...product,icon:'Package'}}
if(route==='/inventory/adjustments'&&method==='POST'){const product=products.value.find(item=>item.sku===body.sku),delta=Number(body.delta),reserved=product?demoReserved(product.sku):0;if(!product||!Number.isInteger(delta)||delta===0)throw new Error('库存调整信息无效');if(product.stock+delta<reserved)throw new Error('调整后库存不能低于已预占数量');product.stock+=delta;addDemoLedger({sku:product.sku,type:'adjust',quantityDelta:delta,note:String(body.reason||'手动调整')});saveDemoData();return{ok:true}}
if(route==='/backups/status')return{remoteConfigured:false,remoteType:null,remoteCredentialMode:'unconfigured',configurationIssue:'演示模式备份保存在当前浏览器，不会同步到云端。',retentionCount:10,automaticIntervalHours:null,remoteRetryIntervalMinutes:null,pendingRemoteCount:0,latestBackupName:readDemoBackups()[0]?.name||null,latestBackupRemoteUploaded:false};if(route==='/backups'&&method==='GET')return readDemoBackups().map(({snapshot,...backup})=>backup);if(route==='/backups'&&method==='POST'){const current={products:products.value.map(product=>({...product,icon:demoIconName(product.icon)})),orders:orders.value,inventoryLedger:inventoryLedger.value},content=JSON.stringify(current),name=`tradeflow-demo-${new Date().toISOString().replace(/[:.]/g,'-')}.json`,records=readDemoBackups();records.unshift({name,createdAt:new Date().toISOString(),size:new Blob([content]).size,remoteUploaded:false,snapshot:content});localStorage.setItem(DEMO_BACKUP_KEY,JSON.stringify(records.slice(0,10)));return{name,createdAt:records[0].createdAt,size:records[0].size,remoteUploaded:false}}
if(route.includes('/backups/')&&route.endsWith('/restore')&&method==='POST'){if(body.confirmation!=='RESTORE')throw new Error('请输入 RESTORE 确认');const name=decodeURIComponent(route.split('/').filter(Boolean).at(-2)||''),record=readDemoBackups().find(item=>item.name===name);if(!record?.snapshot)throw new Error('找不到这份浏览器备份');const snapshot=JSON.parse(record.snapshot),icons={BriefcaseBusiness,Activity,Globe2,Lightbulb,PackageCheck,Package};products.value=snapshot.products.map(product=>({...product,icon:icons[product.icon]||Package}));orders.value=snapshot.orders;inventoryLedger.value=snapshot.inventoryLedger||[];saveDemoData();return{safetyBackup:'浏览器演示数据快照',name}}
if(route.startsWith('/backups/remote'))return{backups:[],error:'演示模式没有云端备份'};throw new Error(`此操作暂不支持：${route}`)}
async function api(path, options={}){if(DEMO_MODE)return demoApi(path,options);const response=await fetch(`${API_BASE_URL}/api${path}`,{headers:{'Content-Type':'application/json'},...options});const body=await response.json().catch(()=>({}));if(!response.ok){if(response.status===401&&!path.startsWith('/auth/')){currentUser.value=null;authError.value=body.error||'登录已过期，请重新登录'}throw new Error(body.error||'请求失败，请稍后重试')}return body}
async function loadData(){try{const [productRows,orderRows,ledgerRows]=await Promise.all([api('/products'),api('/orders'),api('/inventory/ledger')]);products.value=productRows.map(p=>({...p,icon:({BriefcaseBusiness,Package,Activity,Globe2,Lightbulb,PackageCheck})[p.icon]||Package}));orders.value=orderRows.map(o=>({ ...o,items:o.items.map(i=>({sku:i.sku,qty:i.qty,price:i.price,name:i.name})) }));inventoryLedger.value=ledgerRows}catch(error){showToast(`无法连接后端：${error.message}`,'error')}}
function openDemoOrderForm(){demoOrderError.value='';Object.assign(demoOrderForm,{sku:products.value[0]?.sku||'',quantity:1,country:'美国',shipping:5});showDemoOrderModal.value=true}
async function createDemoOrder(){demoOrderError.value='';demoOrderBusy.value=true;try{const created=await api('/orders/demo',{method:'POST',body:JSON.stringify(demoOrderForm)});orders.value.unshift(created);if(DEMO_MODE)saveDemoData();showDemoOrderModal.value=false;showToast(`测试订单 ${created.id} 已生成`);navigate('orders','processing')}catch(error){demoOrderError.value=error.message;showToast(error.message,'error')}finally{demoOrderBusy.value=false}}
async function confirmOrder(o){if(!o||o.status!=='processing')return;try{const updated=await api(`/orders/${encodeURIComponent(o.id)}/confirm`,{method:'POST'});Object.assign(o,updated);await loadProducts();showToast(`订单 ${o.id} 已确认，已预占库存`)}catch(error){showToast(error.message,'error')}}
function beginCancel(o){if(!o||!['processing','ready'].includes(o.status))return;cancelTarget.value=o;cancelReason.value='';cancelError.value='';showCancelModal.value=true}
async function cancelOrder(){if(cancelReason.value.length<2||cancelReason.value.length>120){cancelError.value='取消原因请填写 2 到 120 个字';return}try{const o=cancelTarget.value;const updated=await api(`/orders/${encodeURIComponent(o.id)}/cancel`,{method:'POST',body:JSON.stringify({reason:cancelReason.value})});Object.assign(o,updated);await loadProducts();showCancelModal.value=false;showToast(`订单 ${o.id} 已取消，库存预占已释放`)}catch(error){cancelError.value=error.message;showToast(error.message,'error')}}
function selectShipment(id){selectedShipmentId.value=id;shipmentForm.carrier='';shipmentForm.tracking='';shipmentErrors.carrier=false;shipmentErrors.tracking=false}
async function submitShipment(){shipmentErrors.carrier=!shipmentForm.carrier;shipmentErrors.tracking=!shipmentForm.tracking;if(shipmentErrors.carrier||shipmentErrors.tracking)return;const o=selectedShipment.value;if(!o||o.status!=='ready')return;try{const updated=await api(`/orders/${encodeURIComponent(o.id)}/ship`,{method:'POST',body:JSON.stringify({carrier:shipmentForm.carrier,tracking:shipmentForm.tracking})});Object.assign(o,updated);await loadProducts();showToast(`订单 ${o.id} 已发货，库存已更新`);selectShipment(shipmentOrders.value[0]?.id||null)}catch(error){showToast(error.message,'error')}}
async function loadUsers(){if(currentUser.value?.role==='admin'){const [rows,audit]=await Promise.all([api('/users'),api('/users/audit')]);users.value=rows;userAuditEvents.value=audit}}
async function loadBackups(){const [items,status]=await Promise.all([api('/backups'),api('/backups/status')]);backups.value=items;backupStatus.value=status;if(!status.remoteConfigured){remoteBackups.value={backups:[],error:''};return}try{remoteBackups.value={...await api('/backups/remote'),error:''}}catch(error){remoteBackups.value={backups:[],error:error.message}}}
async function retryRemoteBackups(){backupBusy.value=true;try{const result=await api('/backups/retry-remote',{method:'POST'});await loadBackups();showToast(result.failed?`已补传 ${result.uploaded} 份，仍有 ${result.failed} 份失败`:`已补传 ${result.uploaded} 份云端备份` ,result.failed?'error':'success')}catch(error){showToast(error.message,'error')}finally{backupBusy.value=false}}
async function createBackup(){backupBusy.value=true;try{const item=await api('/backups',{method:'POST'});await loadBackups();showToast(item.remoteError||`备份已创建：${item.name}${item.remoteConfigured?'（已同步到云端）':''}`,item.remoteError?'error':'success')}catch(error){showToast(error.message,'error')}finally{backupBusy.value=false}}
function beginRestore(name){restoreTarget.value={name,source:'local'};restoreInput.value='';restoreError.value=''}
function beginRemoteRestore(name){restoreTarget.value={name,source:'remote'};restoreInput.value='';restoreError.value=''}
async function restoreBackup(){if(restoreInput.value!=='RESTORE'){restoreError.value='请输入 RESTORE 确认恢复';return}backupBusy.value=true;try{const target=restoreTarget.value,endpoint=target.source==='remote'?`/backups/remote/${encodeURIComponent(target.name)}/restore`:`/backups/${encodeURIComponent(target.name)}/restore`;const result=await api(endpoint,{method:'POST',body:JSON.stringify({confirmation:restoreInput.value})});restoreTarget.value=null;currentUser.value=DEMO_MODE?DEMO_USER:null;authError.value="";showToast(`恢复完成，操作前备份：${result.safetyBackup}`)}catch(error){restoreError.value=error.message}finally{backupBusy.value=false}}
function downloadBackup(name){if(DEMO_MODE){const record=readDemoBackups().find(item=>item.name===name);if(!record?.snapshot){showToast('找不到这份浏览器备份','error');return}const link=document.createElement('a'),url=URL.createObjectURL(new Blob([record.snapshot],{type:'application/json'}));link.href=url;link.download=name;link.click();URL.revokeObjectURL(url);return}window.location.assign(`${API_BASE_URL}/api/backups/${encodeURIComponent(name)}/download`)}
function formatBytes(bytes){if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
async function loadProducts(){const [rows,ledger]=await Promise.all([api('/products'),api('/inventory/ledger')]);products.value=rows.map(p=>({...p,icon:({BriefcaseBusiness,Package,Activity,Globe2,Lightbulb,PackageCheck})[p.icon]||Package}));inventoryLedger.value=ledger}
function openUserForm(){Object.assign(userForm,{username:'',password:'',role:'operator'});userError.value='';showUserModal.value=true}
async function createUser(){userError.value='';if(userForm.password.length<12){userError.value='密码长度至少 12 位';return}try{await api('/users',{method:'POST',body:JSON.stringify(userForm)});showUserModal.value=false;await loadUsers();showToast('用户账号已创建')}catch(error){userError.value=error.message}}
async function updateUser(user,changes){try{await api(`/users/${user.id}`,{method:'PATCH',body:JSON.stringify(changes)});await loadUsers();showToast('用户权限已更新')}catch(error){showToast(error.message,'error');await loadUsers()}}
function openInventoryAdjustment(){Object.assign(inventoryAdjustment,{sku:products.value[0]?.sku||'',delta:1,reason:''});inventoryAdjustmentError.value='';showInventoryAdjustment.value=true}
async function submitInventoryAdjustment(){inventoryAdjustmentError.value='';try{await api('/inventory/adjustments',{method:'POST',body:JSON.stringify(inventoryAdjustment)});showInventoryAdjustment.value=false;await loadProducts();showToast('库存调整已保存并记录操作人和原因')}catch(error){inventoryAdjustmentError.value=error.message;showToast(error.message,'error')}}
function openProductForm(){Object.assign(productForm,{name:'',sku:'',price:'',stock:'',category:'',description:''});productErrors.name='';productErrors.sku='';showProductModal.value=true}
function closeProductForm(){showProductModal.value=false}
async function submitProduct(){productErrors.name=productForm.name?'':'请填写商品名称';productErrors.sku=!productForm.sku?'请填写 SKU':'';if(!productForm.name||productErrors.sku||productForm.price===''||Number(productForm.price)<=0||productForm.stock===''||Number(productForm.stock)<0){if(!productForm.name||productErrors.sku)return;showToast('请填写有效的售价和库存数量','error');return}try{const added=await api('/products',{method:'POST',body:JSON.stringify(productForm)});added.icon=Package;products.value.unshift(added);if(DEMO_MODE){addDemoLedger({sku:added.sku,type:'opening',quantityDelta:added.stock,note:'新增商品期初库存'});saveDemoData()}closeProductForm();showToast(`商品“${added.name}”已添加`)}catch(error){productErrors.sku=error.message;showToast(error.message,'error')}}
async function submitAuth(){authError.value='';if(setupRequired.value&&authForm.password!==authForm.confirmPassword){authError.value='两次输入的密码不一致';return}try{currentUser.value=await api(setupRequired.value?'/auth/setup':'/auth/login',{method:'POST',body:JSON.stringify({username:authForm.username,password:authForm.password,...(setupRequired.value&&setupTokenRequired.value?{setupToken:authForm.setupToken}:{})})});setupRequired.value=false;setupTokenRequired.value=false;authForm.password='';authForm.confirmPassword='';authForm.setupToken='';await loadData();await loadUsers()}catch(error){authError.value=error.message}}
async function logout(){try{await api('/auth/logout',{method:'POST'})}finally{currentUser.value=null;users.value=[];authForm.password='';authError.value=''}}
async function initAuth(){if(DEMO_MODE){currentUser.value=DEMO_USER;loadDemoData();await loadData();authReady.value=true;return}try{const status=await api('/auth/setup-status');setupRequired.value=status.setupRequired;setupTokenRequired.value=Boolean(status.setupTokenRequired);setupBlocked.value=Boolean(status.setupBlocked);if(setupBlocked.value)authError.value='生产初始化暂不可用：服务器未配置 TRADEFLOW_SETUP_TOKEN。';if(!setupRequired.value){currentUser.value=await api('/auth/me');await loadData();await loadUsers()}}catch(error){authError.value=error.message}finally{authReady.value=true}}
async function completeOrder(o){if(!o||o.status!=='shipped')return;try{const updated=await api(`/orders/${encodeURIComponent(o.id)}/complete`,{method:'POST'});Object.assign(o,updated);showToast(`订单 ${o.id} 已完成`)}catch(error){showToast(error.message,'error')}}
function syncRoute(){const previous=workspaceKey(page.value),p=location.hash.replace(/^#\/?/,'').split('/');if(p[0]==='orders'&&p[1]){const o=orders.value.find(x=>x.id===p[1]);if(o){if(previous!=='orders')workspaceHistory.value.push(previous);selectedOrderId.value=o.id;page.value='order-detail';return}}const target=['dashboard','products','orders','shipments','inventory'].includes(p[0])?p[0]:'dashboard';if(target!==previous)workspaceHistory.value.push(previous);page.value=target}
watch(shipmentOrders,list=>{if(!list.some(o=>o.id===selectedShipmentId.value))selectShipment(list[0]?.id||null)})
onMounted(()=>{syncRoute();window.addEventListener('hashchange',syncRoute);initAuth()})
onUnmounted(()=>{window.removeEventListener('hashchange',syncRoute);clearTimeout(toastTimer)})
</script>

